%%\ FIR vs IIR vs Linkwitz-Riley IIR Filter Bank Equalizer  (final script)
% Needs: Signal Processing Toolbox
% Banks compared:
%   1) FIR            (window method, linear phase)
%   2) IIR Butterworth band-pass bank (baseline IIR)
%   3) IIR Linkwitz-Riley bank (our contribution: flat magnitude sum)
clear; clc; close all;

%%\ 1. Settings
fs  = 16000;                          % sampling frequency (Hz)
fc  = 62.5 * 2.^(0:7);                % 8 octave-band centre frequencies
lo  = fc / sqrt(2);                   % lower band edges
hi  = min(fc * sqrt(2), 0.95*fs/2);   % upper band edges (top one kept < Nyquist)
nb  = numel(fc);

gdB = [6 4 2 0 0 -2 -4 -6];           % equalizer setting: dB gain per band
G   = 10.^(gdB/20);                   % same, as linear gains

N   = 1000;                           % FIR order
Nbw = 3;                              % Butterworth order (band-pass -> 6th order)

f    = linspace(0, fs/2, 8192)';      % frequency grid (Hz)
w    = 2*pi*f/fs;                     % same grid in rad/sample
mask = f >= fc(1) & f <= 6000;        % range where we measure errors

% Target = ideal staircase (each band should have exactly its own gain)
fm  = f(mask);
idx = zeros(size(fm));
for k = 1:nb
    idx(fm >= lo(k) & fm < hi(k)) = k;
end
target = gdB(idx);
target = target(:);                   % force column (gdB is a row, so gdB(idx) comes out as a row)

%%\ 2. Design bank 1 (FIR) and bank 2 (Butterworth IIR)
h = cell(nb,1);  sos = cell(nb,1);  sg = zeros(nb,1);
Hf = zeros(numel(f), nb);   Hb = zeros(numel(f), nb);
for k = 1:nb
    Wn = [lo(k) hi(k)] / (fs/2);
    h{k} = fir1(N, Wn, 'bandpass');
    [z,p,kk] = butter(Nbw, Wn, 'bandpass');
    [sos{k}, sg(k)] = zp2sos(z,p,kk);
    Hf(:,k) = freqz(h{k}, 1, w);
    Hb(:,k) = sosResp(sos{k}, sg(k), w);
end

%%\ 3. Design bank 3 (Linkwitz-Riley IIR)  <-- contribution
% Crossover frequencies = band edges. Each LR4 filter = 2 cascaded 2nd-order
% Butterworth filters. LP + HP of an LR4 pair is an all-pass (|H| = 1), so
% bands built from a tree of crossovers sum to a flat magnitude response.
M  = nb - 1;                          % number of crossovers
fx = hi(1:M);
bl = cell(M,1); al = cell(M,1); bh = cell(M,1); ah = cell(M,1);
LP = zeros(numel(f), M);  HP = LP;
for j = 1:M
    [bl{j}, al{j}] = butter(2, fx(j)/(fs/2), 'low');
    [bh{j}, ah{j}] = butter(2, fx(j)/(fs/2), 'high');
    LP(:,j) = freqz(bl{j}, al{j}, w).^2;       % LR4 low-pass
    HP(:,j) = freqz(bh{j}, ah{j}, w).^2;       % LR4 high-pass
end
AP = LP + HP;                         % all-pass of each crossover
Hl = zeros(numel(f), nb);
Hl(:,1) = prod(LP, 2);
for j = 1:M
    % band j+1 = HP_j * (all LPs above j) * (all-passes of crossovers below j)
    Hl(:,j+1) = prod(LP(:,j+1:M), 2) .* HP(:,j) .* prod(AP(:,1:j-1), 2);
end

%%\ 4. Metrics
mF = bankMetrics(Hf, G, w, fs, mask, target);
mB = bankMetrics(Hb, G, w, fs, mask, target);
mL = bankMetrics(Hl, G, w, fs, mask, target);

multF = nb * (N+1);                              % multiplications per sample
multB = nb * (5*size(sos{1},1) + 1);
biqL  = sum(4 * (1 + (nb - (1:M) - 1)));         % biquad filterings in the LR tree
multL = 5*biqL + nb;

T = table(["FIR";"IIR Butterworth";"IIR Linkwitz-Riley"], ...
    [mF.rms; mB.rms; mL.rms], [mF.max; mB.max; mL.max], ...
    [mF.rip; mB.rip; mL.rip], [mF.gdv; mB.gdv; mL.gdv], ...
    [mF.gdm; mB.gdm; mL.gdm], [multF; multB; multL], ...
    'VariableNames', {'Bank','RMS_err_dB','Max_err_dB','Flat_ripple_dB', ...
    'GD_variation_ms','Mean_delay_ms','Mults_per_sample'});
disp(T); %[output:917b6e08]

%%\ 5. Plots
db = @(H) 20*log10(abs(H) + eps);

figure('Name','Individual bands'); %[output:41c49934]
subplot(3,1,1); semilogx(f, db(Hf)); title('FIR bands'); %[output:41c49934]
subplot(3,1,2); semilogx(f, db(Hb)); title('Butterworth IIR bands'); %[output:41c49934]
subplot(3,1,3); semilogx(f, db(Hl)); title('Linkwitz-Riley IIR bands'); %[output:41c49934]
for a = 1:3, subplot(3,1,a); grid on; ylim([-60 5]); xlim([20 fs/2]); ylabel('dB'); end %[output:41c49934]
xlabel('Hz'); %[output:41c49934]

figure('Name','EQ response vs target'); %[output:2f371edc]
semilogx(f(mask), target, 'k--', f(mask), db(Hf(mask,:)*G(:)), 'b', ... %[output:2f371edc]
         f(mask), db(Hb(mask,:)*G(:)), 'r', f(mask), db(Hl(mask,:)*G(:)), 'g'); %[output:2f371edc]
grid on; xlabel('Hz'); ylabel('dB'); %[output:2f371edc]
legend('Target','FIR','IIR Butterworth','IIR Linkwitz-Riley'); %[output:2f371edc]

figure('Name','Flatness (all gains 0 dB)'); %[output:682ca6f0]
semilogx(f(mask), db(sum(Hf(mask,:),2)), 'b', f(mask), db(sum(Hb(mask,:),2)), 'r', ... %[output:682ca6f0]
         f(mask), db(sum(Hl(mask,:),2)), 'g'); %[output:682ca6f0]
grid on; xlabel('Hz'); ylabel('dB'); ylim([-3 1]); %[output:682ca6f0]
legend('FIR','IIR Butterworth','IIR Linkwitz-Riley'); %[output:682ca6f0]

figure('Name','Group delay of the whole bank'); %[output:7cbbf66e]
semilogx(f(1:end-1), mF.gd, 'b', f(1:end-1), mB.gd, 'r', f(1:end-1), mL.gd, 'g'); %[output:7cbbf66e]
grid on; xlabel('Hz'); ylabel('ms'); xlim([50 6000]); %[output:7cbbf66e]
legend('FIR','IIR Butterworth','IIR Linkwitz-Riley'); %[output:7cbbf66e]

%%\ 6. Test on white noise (full bandwidth, so every band gets tested)
rng(1);
xn = randn(10*fs, 1);

yF = zeros(size(xn));  yB = zeros(size(xn));  yL = zeros(size(xn));
yFlat = zeros(size(xn));
bandsL = lrBands(xn, bl, al, bh, ah);
for k = 1:nb
    yF    = yF + G(k) * filter(h{k}, 1, xn);
    yB    = yB + G(k) * sosApply(sos{k}, sg(k), xn);
    yL    = yL + G(k) * bandsL{k};
    yFlat = yFlat + bandsL{k};
end
fprintf('LR time-domain check, all gains 0 dB: energy ratio = %.4f (should be ~1)\n', ... %[output:group:46b3666b] %[output:01475634]
    sum(yFlat.^2)/sum(xn.^2)); %[output:group:46b3666b] %[output:01475634]

[Pxx, fp] = pwelch(xn, 2048, 1024, 2048, fs);
Pf = pwelch(yF, 2048, 1024, 2048, fs);
Pb = pwelch(yB, 2048, 1024, 2048, fs);
Pl = pwelch(yL, 2048, 1024, 2048, fs);
figure('Name','Measured EQ response (white noise test)'); %[output:2d7b2ba5]
semilogx(f(mask), target, 'k--', fp, 10*log10(Pf./Pxx), 'b', ... %[output:2d7b2ba5]
         fp, 10*log10(Pb./Pxx), 'r', fp, 10*log10(Pl./Pxx), 'g'); %[output:2d7b2ba5]
grid on; xlim([50 7000]); ylim([-10 10]); xlabel('Hz'); ylabel('dB'); %[output:2d7b2ba5]
legend('Target','FIR','IIR Butterworth','IIR Linkwitz-Riley'); %[output:2d7b2ba5]

% To listen on music instead (optional):
% load handel; xm = resample(y(:,1), fs, Fs); xm = xm/max(abs(xm)); soundsc(xm, fs);

%%\ 7. FIR order sweep (how large must the FIR order be?)
orders = [200 400 600 800 1000 1500 2000];
rmsSweep = zeros(size(orders));
for n = 1:numel(orders)
    H = zeros(numel(f), 1);
    for k = 1:nb
        hk = fir1(orders(n), [lo(k) hi(k)]/(fs/2), 'bandpass');
        H = H + G(k) * freqz(hk, 1, w);
    end
    rmsSweep(n) = sqrt(mean((db(H(mask)) - target).^2));
end
figure('Name','FIR order vs error'); %[output:3f27aebf]
plot(orders, rmsSweep, '-o'); grid on; %[output:3f27aebf]
xlabel('FIR order'); ylabel('RMS error vs target (dB)'); %[output:3f27aebf]
yline(mB.rms, 'r--', 'IIR Butterworth'); %[output:3f27aebf]
yline(mL.rms, 'g--', 'IIR Linkwitz-Riley'); %[output:3f27aebf]

%%\ Local functions
function H = sosResp(sos, g, w)
    H = g * ones(numel(w), 1);
    for r = 1:size(sos,1)
        H = H .* freqz(sos(r,1:3), sos(r,4:6), w(:));
    end
end

function y = sosApply(sos, g, x)
    y = g * x;
    for r = 1:size(sos,1)
        y = filter(sos(r,1:3), sos(r,4:6), y);
    end
end

function y = lr4(b, a, x)             % Linkwitz-Riley 4th order = two passes
    y = filter(b, a, filter(b, a, x));
end

function bands = lrBands(x, bl, al, bh, ah)
    M = numel(bl);  nb = M + 1;
    bands = cell(nb, 1);
    u = x;
    for j = M:-1:1
        for m = j+2:nb                 % all-pass the bands created earlier
            bands{m} = lr4(bl{j}, al{j}, bands{m}) + lr4(bh{j}, ah{j}, bands{m});
        end
        bands{j+1} = lr4(bh{j}, ah{j}, u);   % band above this crossover
        u          = lr4(bl{j}, al{j}, u);   % remainder continues downward
    end
    bands{1} = u;
end

function m = bankMetrics(H, G, w, fs, mask, target)
    err  = 20*log10(abs(H(mask,:) * G(:))) - target;
    S    = sum(H, 2);                          % response with all gains = 0 dB
    flat = 20*log10(abs(S));
    gd   = -diff(unwrap(angle(S))) ./ diff(w) / fs * 1000;   % group delay, ms
    m2   = mask(1:end-1);
    m.rms = sqrt(mean(err.^2));
    m.max = max(abs(err));
    m.rip = max(flat(mask)) - min(flat(mask));
    m.gdv = max(gd(m2)) - min(gd(m2));
    m.gdm = mean(gd(m2));
    m.gd  = gd;
end

